       specs:[["Диапазон измерения","1 – 100 метров"],["Точность","0,5%"],["Максимальное давление","200% от верхнего предела"],["Электрическое присоединение","Длина кабеля в соответствии со значением уровня"],["Напряжение питания","+12…30 В DC"],["Степень защиты","IP68"],["Корпус","1.4404 (AISI 316L), опц. 1.4462 (дуплекс) – титан"],["Рабочая температура","−25…+85 °C"],["Выход","4–20 мА, 0–10 В DC или 0,5–4,5 В DC"]],
